mapper.sql:
WHERE deleted = 0
    AND (code LIKE #{keyword} OR name LIKE #{keyword})
    AND status = #{status}

WHERE p.deleted = 0
    AND (p.code LIKE #{keyword} OR p.name LIKE #{keyword})
    AND p.status = #{status}

WHERE o.deleted = 0
    AND (o.code LIKE #{keyword} OR o.name LIKE #{keyword})
    AND o.perspective_id = #{perspectiveId}
    AND o.status = #{status}
